    </x-core::form>

    <script>
        document.addEventListener('DOMContentLoaded', function () {
            const qtyInput = document.querySelector('input[name="qty"]');
            const increaseBtn = document.querySelector('[data-bb-toggle="increase-qty"]');
            const decreaseBtn = document.querySelector('[data-bb-toggle="decrease-qty"]');

            // تابع افزایش مقدار
            increaseBtn.addEventListener('click', function () {
                if (qtyInput.disabled) return;

                let currentValue = parseInt(qtyInput.value) || 0;
                let maxValue = parseInt(qtyInput.max) || Infinity;

                if (currentValue < maxValue) {
                    qtyInput.value = currentValue;
                }
            });

            // تابع کاهش مقدار
            decreaseBtn.addEventListener('click', function () {
                if (qtyInput.disabled) return;

                let currentValue = parseInt(qtyInput.value) || 0;
                let minValue = parseInt(qtyInput.min) || 0;

                if (currentValue > minValue) {
                    qtyInput.value = currentValue - 1;
                }
            });
        });

    </script>
</div>

